function resourceRow(a){let ci=D.categories.find(c=>c.name===a.category)||{icon:'book',color:'#70aa9c'};return `<div class="resource-row" role="button" tabindex="0" ${opener('article',a.id)}><span class="res-icon" style="background:${ci.color}1d;color:${ci.color}">${ico(ci.icon,18)}</span><div class="res-main"><div class="res-title">${h(a.title)}</div><div class="res-meta"><span>${h(a.category)}</span><span class="small-bullet"></span><span>${a.minutes} min read</span></div></div><div class="row-tail"><span class="tag ${a.level==='Essential'?'':'grey'}">${a.level==='Essential'?'Essential':'Reference'}</span>${ico('chevron',14)}</div></div>`;}
